"""Проклятие размерности: расчёт таблицы из раздела «Ограничения» страницы 4.1 курса «Аналитика 101».

1 000 случайных точек с независимыми стандартизованными признаками и ещё одна точка.
Для 2, 3, 10, 100 и 500 признаков считаем расстояние от неё до ближайшей и до самой далёкой точки
и долю точек, чей вектор почти перпендикулярен её вектору: |cos| < 0,1. Данные учебные, зерно 4.

Запуск: python curse.py — файлы данных не нужны.
"""
import numpy as np

rng = np.random.default_rng(4)
print("признаков  ближайшая  самая далёкая  во сколько раз  |cos| < 0,1")
for d in [2, 3, 10, 100, 500]:
    P = rng.standard_normal((1000, d))            # 1 000 точек: среднее 0 и разброс 1 по каждому признаку
    q = rng.standard_normal(d)                    # ещё одна точка
    dist = np.sqrt(((P - q) ** 2).sum(axis=1))    # (1000, d) − (d,), сумма по признакам → (1000,)
    cos = P @ q / (np.linalg.norm(P, axis=1) * np.linalg.norm(q))
    print(f"{d:>9}  {dist.min():>9.2f}  {dist.max():>13.2f}  {dist.max() / dist.min():>14.1f}  {np.mean(np.abs(cos) < 0.1):>11.0%}")

# Вывод:
# признаков  ближайшая  самая далёкая  во сколько раз  |cos| < 0,1
#         2       0.10           4.81            49.6           7%
#         3       0.21           5.89            28.0          10%
#        10       1.86           7.48             4.0          23%
#       100      10.93          16.12             1.5          69%
#       500      29.34          34.97             1.2          98%
